INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40425, 0, 0, 0, 0, 0, 0, 0, 0, 'My my... This is it, the rare volume! I never thought I would lay my eyes upon it!$B$BYou\'ve done us a great favor in getting this, and favors should always be repaid.$B$BOn behalf of the Academy of Arcane Arts and Sciences, I present you with this.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40425, 0, 0, 'Have you delved within the depths of that accursed Vault, and recovered the rare tome? Or is it still collecting dust with chance of desecration?', 0);
